CREATE FUNCTION pg_temp.check_c(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAILED: %',message; END IF; END $$;
CREATE FUNCTION pg_temp.reject_c(statement text,expected text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 EXECUTE statement;RAISE EXCEPTION 'Unexpected success: %',statement;
 EXCEPTION WHEN OTHERS THEN IF SQLSTATE<>expected THEN RAISE; END IF;END $$;
GRANT EXECUTE ON FUNCTION pg_temp.check_c(boolean,text),pg_temp.reject_c(text,text) TO anon,authenticated,service_role;
CREATE TEMP TABLE credential_versions(version uuid,revision bigint);
